package integration

import (
	"context"
	"testing"

	"entgo.io/ent"
	ent2 "entgo.io/ent/entc/integration/ent"
	"entgo.io/ent/entc/integration/ent/enttest"
	"entgo.io/ent/entc/integration/ent/pet"
	"entgo.io/ent/entc/integration/ent/user"

	"github.com/stretchr/testify/require"
)

// Reproduces the multi-tenancy issue #4509: traversers/interceptors are not
// applied to the sub-queries generated by HasX / HasXWith predicates.
func TestReproTenantInterceptors(t *testing.T) {
	client := enttest.Open(t, "sqlite3", "file:ent_repro?mode=memory&cache=shared&_fk=1")
	defer client.Close()
	ctx := context.Background()

	a8m := client.User.Create().SetName("a8m").SetAge(30).SaveX(ctx)
	nati := client.User.Create().SetName("nati").SetAge(30).SaveX(ctx)
	client.Pet.Create().SetName("xabi").SetOwner(a8m).SaveX(ctx)
	client.Pet.Create().SetName("luna").SetOwner(nati).SaveX(ctx)

	// "Tenant" filter that only sees pets named "xabi".
	client.Intercept(ent.TraverseFunc(func(ctx context.Context, q ent.Query) error {
		switch q := q.(type) {
		case *ent2.PetQuery:
			q.Where(pet.Name("xabi"))
		}
		return nil
	}))

	// Direct pet queries are scoped.
	require.Equal(t, 1, client.Pet.Query().CountX(ctx))
	// Graph traversal from user to pets is scoped (traverser applied).
	require.Equal(t, 1, client.User.Query().QueryPets().CountX(ctx))
	// HasPets predicate: the sub-query on pets bypasses the traverser.
	t.Logf("HasPets count: %d", client.User.Query().Where(user.HasPets()).CountX(ctx))
	// HasPetsWith: also bypasses — nati's pet luna is invisible to the tenant, so
	// asking for users having pets named "luna" should return 0.
	t.Logf("HasPetsWith(luna) count: %d", client.User.Query().Where(user.HasPetsWith(pet.Name("luna"))).CountX(ctx))
	_ = enttest.Open
}
